window.DIGEST.foryou.push(...[{"id": "2112997119925583942", "url": "https://x.com/GoogleForEdu/status/2112997119925583942", "text": "Save this Gemini tip for your next lecture refresh or research draft! 📚\n\nWatch how Dr. Marian Stoltz-Loike from @TouroUniversity uses the @GeminiApp to catch missing citations and stress-test her arguments with a fresh perspective.\n\nGive it a try here → https://goo.gle/3WnRMaN", "name": "Google for Education", "handle": "GoogleForEdu", "avatar": "https://pbs.twimg.com/profile_images/1455292838934102017/C1ntsrVO_200x200.jpg", "likes": 17, "rts": 6, "replies": 1, "views": 2734, "ts": 1792612745, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112997049901740032/vid/avc1/720x1280/UuRGafzGp_KF1J6p.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112997049901740032/vid/avc1/1080x1920/4aiUyJFIfx4U7b-E.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112997049901740032/img/_P7Vdm98R4tG2929.jpg", "dur": 56}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.08, "thread": [], "tier": "worth"}, {"id": "2113080709128884574", "url": "https://x.com/MTSlive/status/2113080709128884574", "text": "Flapping Airplanes co-founder @aidanmantine reveals how he attracts top AI talent by trying to talk candidates out of joining his own lab:\n\n\"When people interview with us, we counter sell them a ton. If they wanna go work at OpenAI or Anthropic, they should go do that. You should go to Flapping Airplanes if you wanna be part of the last age in human history where you can do research.\"\n\n\"It's really easy to go into a big org and hide under the floorboards. At Flapping Airplanes, you own this thing that's really important. This project will live or die on your success.\"\n\n\"We've had some people inbound us who are very radically different, like a Clash of Clans world champion, who you interview and you're like, holy crap, this guy is really smart.\"\n\n\"We have lots of IMO medalists, but also lots of IMO medalists are maybe not the best machine learning people.\"\n@flappyairplanes", "name": "MTS", "handle": "MTSlive", "avatar": "https://pbs.twimg.com/profile_images/2057947669281263616/aovpVL4b_200x200.jpg", "likes": 23, "rts": 1, "replies": 1, "views": 4802, "ts": 1792632674, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2113080649875947520/vid/avc1/640x360/R0ZEUe3xlYTFwKJg.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2113080649875947520/vid/avc1/1280x720/tRoN7R0HtXfhuR9u.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2113080649875947520/img/qnncpnTUOcjlgrpW.jpg", "dur": 129}], "quote": {"id": "2113067421376585965", "url": "https://x.com/MTSlive/status/2113067421376585965", "text": "FULL INTERVIEW: Flapping Airplanes just raised a $1B Series A after rebuilding the GPU stack from scratch. Co-founder Aidan Smith says they don’t even use Torch, NCCL or CUDA’s normal runtime. One kernel on one B200 can now train a model, serve inference and play Doom at the same time.\n\n@aidanmantine, Thiel Fellow and 3-year Neuralink alum, co-founded @flappyairplanes. He joined @sophiadew and @theojaffee to break down why AI needs to learn more like the brain, how they rebuilt the GPU stack, and who they hire:\n\n00:30 where the name Flapping Airplanes comes from\n02:04 why they bet on data efficiency\n03:07 what Neuralink taught him about AI\n04:27 how slow your brain actually is\n06:06 why not just emulate the whole brain\n08:40 why they rebuilt the GPU stack from scratch\n10:33 compute overhang and safety\n12:56 can a neo lab win if the big labs hit RSI first\n14:27 what ML research looks like when no one writes code\n15:40 why DNA, robotics and trading are data-starved\n18:41 how they hire in the AI talent wars\n21:17 the models they might ship first", "name": "MTS", "handle": "MTSlive", "avatar": "https://pbs.twimg.com/profile_images/2057947669281263616/aovpVL4b_200x200.jpg", "likes": 156, "rts": 11, "replies": 2, "views": 25300, "ts": 1792629506, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2113065770674786304/vid/avc1/1280x720/cIOkwz0WSSaiLA-a.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2113065770674786304/vid/avc1/1920x1080/cMf5cDpIS9AmOoay.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2113065770674786304/img/2jHGVFH-uGgh5YLt.jpg", "dur": 1391}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.08, "thread": [], "tier": "worth"}, {"id": "2112967153221558610", "url": "https://x.com/lovart_ai/status/2112967153221558610", "text": "Your team's notes, turned into revisions.\n\nFeedback Revisions: collaborators comment on your canvas, and Arti acts on those comments in one click.\n\nArti, your first personal design agent, has memory and takes initiative. Now in Lovart 2.0.\n\n#BuiltWithLovart", "name": "Lovart AI", "handle": "lovart_ai", "avatar": "https://pbs.twimg.com/profile_images/2065372538763694080/KSuXj3OU_200x200.jpg", "likes": 22, "rts": 3, "replies": 5, "views": 1138, "ts": 1792605601, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112635329987715072/vid/avc1/1280x720/x8OJir6jV1_8YZ0D.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112635329987715072/vid/avc1/1920x1080/d95d7eclGDySmbDk.mp4?tag=29", "thumb": "https://pbs.twimg.com/media/HVGYgcHaUAAgwfK.jpg", "dur": 19}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.08, "thread": [], "tier": "worth"}, {"id": "2113090126406635638", "url": "https://x.com/chongdashu/status/2113090126406635638", "text": "Here's a longer gameplay video of the my cosy low poly 3d game Retro del Sol.\n\nIt was made with Opus 5.5 and GPT 6 Astra - all assets by Retro Diffusion 3D and animated in Blender.\n\nFully multiplayer and online in your browser.\n\nWorks on mobile and desktop.", "name": "Chong-U", "handle": "chongdashu", "avatar": "https://pbs.twimg.com/profile_images/2109521104167661568/eKr4dw03_200x200.jpg", "likes": 20, "rts": 1, "replies": 2, "views": 879, "ts": 1792634920, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2113089437748035584/vid/avc1/1280x720/699sAiYP-8-9sF0R.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2113089437748035584/vid/avc1/1920x1080/ZDFRzH5CKuZ6Bc63.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2113089437748035584/img/Ppb3v7Rd_47sDHCq.jpg", "dur": 44}], "quote": {"id": "2112781775034581050", "url": "https://x.com/chongdashu/status/2112781775034581050", "text": "I just made Retro del Sol - a beautiful, low-poly pixel art world.\n\nPowered by Retro Diffusion for the art assets \n(yes, it does 3D & is amazing!)\n\nHighlights:\n→ Fully persistent MULTIPLAYER world \n→ Day-night cycles\n→ Vehicles\n→ Character customisation\n\nYou can deliver parcels to earn money or simply travel around the different islands.\n\nPlay it: https://retrodelsol.com \n\nWorks right in your browser and on mobile.", "name": "Chong-U", "handle": "chongdashu", "avatar": "https://pbs.twimg.com/profile_images/2109521104167661568/eKr4dw03_200x200.jpg", "likes": 31, "rts": 3, "replies": 9, "views": 3324, "ts": 1792561403, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112781330060840960/vid/avc1/1280x720/0x8i5osDdPVbq23n.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112781330060840960/vid/avc1/1920x1080/kCFzrhi9mwR0ytKF.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112781330060840960/img/PHfcGun_CBueJ7Ol.jpg", "dur": 62}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.08, "thread": [], "tier": "worth"}, {"id": "2112838909491130373", "url": "https://x.com/WasimShips/status/2112838909491130373", "text": "5 useful websites to keep in your vibe coding toolkit. Save these ↓\n\n- https://vibeindex.dev\n- https://transitions.dev\n- https://reelfolio.io\n- https://skill-issue.in\n- https://motion.dev\n\nBookmark this before your next project 🔖", "name": "Wasim", "handle": "WasimShips", "avatar": "https://pbs.twimg.com/profile_images/2112231529124597760/iBMCSwKl_200x200.jpg", "likes": 51, "rts": 2, "replies": 2, "views": 1656, "ts": 1792575025, "media": [{"type": "video", "url": "https://video.twimg.com/ext_tw_video/2112838880399400960/pu/vid/avc1/720x360/CvpDdQ2NKBPThAkI.mp4?tag=12", "hd": "https://video.twimg.com/ext_tw_video/2112838880399400960/pu/vid/avc1/1440x720/EDmo-u8FlqPbWGtj.mp4?tag=12", "thumb": "https://pbs.twimg.com/ext_tw_video_thumb/2112838880399400960/pu/img/65eO0GGWJ_9Ovxba.jpg", "dur": 16}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.07, "thread": [], "tier": "worth"}, {"id": "2112990442916544639", "url": "https://x.com/aifindr/status/2112990442916544639", "text": "DEEPSEEK JUST GAVE AWAY THE ENGINE BEHIND 155 TRILLION TOKENS A DAY.\nIT KEPT ONE PART: THE PART THAT REMEMBERS.\n\nyesterday: 89.5M tokens for 54 cents, almost all cache hits.\nnow deepseek showed the kitchen. from their own writeup:\n> one cluster: 155 trillion tokens a day\n> $38 revenue per gpu per hour, at off peak prices\n> kv cache built to live 72+ hours, so yesterday's context can still be a hit\n> prefill on 8 gpu boxes, decode on 64 to 128 gpu supernodes\n> runs on nvidia and huawei ascend\n\nwhat's open:\n> deepinfer, the engine\n> deepseek recipe, the layer that turns api calls into tokens\n\nwhat's not open yet:\n> kv cache management and load balancing. \"deeply coupled with the internal infrastructure\"\n\nso you can run the whale yourself.\nyou just can't copy its memory.\n\nthe engine is free. the memory is the moat.\n\none stack, real receipts. a new one every day.", "name": "Findr", "handle": "aifindr", "avatar": "https://pbs.twimg.com/profile_images/2091996856666497025/mdHBHEO0_200x200.jpg", "likes": 24, "rts": 3, "replies": 2, "views": 428, "ts": 1792611153, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112990341083045889/vid/avc1/720x900/B76Vzt_uVB9jtvOP.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112990341083045889/vid/avc1/1080x1350/2zYkgejc6YcnmKsO.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112990341083045889/img/4ww5xKKv-cOx5CTn.jpg", "dur": 19}], "quote": {"id": "2112588380416647205", "url": "https://x.com/latentspacepod/status/2112588380416647205", "text": "https://x.com/i/article/2112587682538987520", "name": "Latent.Space", "handle": "latentspacepod", "avatar": "https://pbs.twimg.com/profile_images/1888346877428641792/rMxtG84Z_200x200.jpg", "likes": 427, "rts": 50, "replies": 7, "views": 88465, "ts": 1792515294, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.07, "thread": [], "tier": "worth"}, {"id": "2112897119694492051", "url": "https://x.com/PedroRonchi2/status/2112897119694492051", "text": "Um golpe atrás do outro.", "name": "Pedro Ronchi", "handle": "PedroRonchi2", "avatar": "https://pbs.twimg.com/profile_images/1276959793752739840/AWCBYwbE_200x200.jpg", "likes": 2360, "rts": 1430, "replies": 708, "views": 13478, "ts": 1792588903, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVKEuiuWgAEnVSX.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 5.07, "thread": [], "tier": "worth"}, {"id": "2113004438168146050", "url": "https://x.com/PennyLedgerr/status/2113004438168146050", "text": "ELON MUSK LIVED INSIDE HIS OWN FACTORIES FOR 3 YEARS. HE SLEPT ON THE FLOOR UNDER HIS DESK, AND HE HAD A REASON FOR IT\n\nhe had a couch. a small room with a door. he stopped using it on purpose.\n\nwhat happens in this clip:\n\n→ 0:00 \"is this you?\" \"it's literally me\"\n→ 0:05 fremont and nevada. 3 years straight. \"that was my primary residence\"\n→ 0:20 for a while he slept in a tent on the roof\n→ 0:25 then under his desk, out in the open, in the middle of the factory\n→ 0:36 \"i'd wake up and smell like metal dust\"\n→ 0:47 he slept there so the whole team could see him at shift change\n→ 1:08 \"i could have been drinking mai tais on a tropical island\"\n→ 1:31 \"they knew i was there. and that made a huge difference\"\n\nwhat actually got me is 1:15. \"i'm not actually a masochist.\"\n\nhe isn't saying it was fun. he says he would have much preferred the island.\n\nto be fair, part of this is a show, and he admits it. a desk out in the open, timed to shift change, is a message to the team.\n\nbut it worked. in the last week of june 2018, tesla built 5,000 model 3s in 7 days. nobody thought it would happen.\n\nthe floor wasn't about sleep. it was about being seen at 6am, when the next shift walks in.", "name": "Penny Ledger", "handle": "PennyLedgerr", "avatar": "https://pbs.twimg.com/profile_images/2109928028520255488/Nb8p4H6h_200x200.jpg", "likes": 25, "rts": 2, "replies": 2, "views": 1107, "ts": 1792614490, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2113004104876163072/vid/avc1/1280x720/cc3pjMl0ltx6D6kL.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2113004104876163072/vid/avc1/1920x1080/IfqU7T7BWV_1wZli.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2113004104876163072/img/qL-dBDuCtqHQ1wHZ.jpg", "dur": 109}], "quote": {"id": "2112941801510178862", "url": "https://x.com/elonmusk/status/2112941801510178862", "text": "Send 𝕏 links to your friends so that they know what’s really going on", "name": "Elon Musk", "handle": "elonmusk", "avatar": "https://pbs.twimg.com/profile_images/2103567689515954176/aR-Kjpp4_200x200.jpg", "likes": 41556, "rts": 6569, "replies": 2227, "views": 22423064, "ts": 1792599556, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.07, "thread": [], "tier": "worth"}, {"id": "2112897189085335670", "url": "https://x.com/draginol/status/2112897189085335670", "text": "So in Clairvoyance you can make a game as an exhibit and from the app share it.  They show up here.  https://www.clairvoyanceai.com/vibecandy/browse?category=game\n\nStardock is interested in seeing what the next-generation of game designers might come up with.  Who would be interested in a contest (cash prizes, etc.).   Some simple examples of games I've made are in the comments here.  Comment here if you're interested. RT if your followers might be interested.", "name": "Brad Wardell", "handle": "draginol", "avatar": "https://pbs.twimg.com/profile_images/1683478767140782087/sXwg3qm1_200x200.png", "likes": 18, "rts": 7, "replies": 5, "views": 1381, "ts": 1792588920, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVHSaxWXsAAI4F0.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.06, "thread": [], "tier": "worth"}, {"id": "2112963575916667078", "url": "https://x.com/aaron_epstein/status/2112963575916667078", "text": "Most founders aren't manually reviewing their code anymore. Now with @Simulithic, they won't need to test it either.\n\nCongrats on the launch @KlausCodes @itsnotryan!", "name": "Aaron Epstein", "handle": "aaron_epstein", "avatar": "https://pbs.twimg.com/profile_images/2338161911/pz9ls0fzhgdo2keracz9_200x200.jpeg", "likes": 25, "rts": 2, "replies": 4, "views": 2001, "ts": 1792604748, "media": [], "quote": {"id": "2112936964307800219", "url": "https://x.com/KlausCodes/status/2112936964307800219", "text": "Shipping code shouldn’t mean hours of manual testing.\n\n@Simulithic (YC F26) sends AI agents through your app like real users, across browsers, devices, and account types. It tells you what broke without you writing a single test script.\n\nThe teams that ship fastest will be the ones that can verify as fast as they build.\n\nGet started today: http://simulithic.com", "name": "Satyam", "handle": "KlausCodes", "avatar": "https://pbs.twimg.com/profile_images/2077048690481541120/TI93G7Uz_200x200.jpg", "likes": 444, "rts": 80, "replies": 167, "views": 28053, "ts": 1792598403, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112933886099652609/vid/avc1/1280x720/vqe5yKAVhgZxDEv8.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112933886099652609/vid/avc1/1920x1080/qNtX8IEcQlvb4QSA.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112933886099652609/img/8R9ks6ybHUChytUw.jpg", "dur": 83}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.06, "thread": [], "tier": "worth"}, {"id": "2112989800575733918", "url": "https://x.com/ScuderiaFerrari/status/2112989800575733918", "text": "Taking the wraps off our special Austin livery 🇺🇸", "name": "Scuderia Ferrari HP", "handle": "ScuderiaFerrari", "avatar": "https://pbs.twimg.com/profile_images/947659786555940865/P5eYYYIx_200x200.jpg", "likes": 4568, "rts": 362, "replies": 110, "views": 251783, "ts": 1792611000, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112963859900243968/vid/avc1/1280x720/rmEUKNevLiwnd_CZ.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112963859900243968/vid/avc1/3840x2160/2OMvewt16uPgc3yc.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112963859900243968/img/bgdLxccoDqQ1mnaY.jpg", "dur": 57}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 5.06, "thread": [], "tier": "worth"}, {"id": "2112926510973948266", "url": "https://x.com/Alhilal_FC/status/2112926510973948266", "text": "وصلنا 💙🎬", "name": "نادي الهلال السعودي", "handle": "Alhilal_FC", "avatar": "https://pbs.twimg.com/profile_images/1561793965359235073/354zGAdx_200x200.jpg", "likes": 4372, "rts": 782, "replies": 202, "views": 420953, "ts": 1792595911, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112925645848117248/vid/avc1/720x900/WaGbwC9XI46Cx2V_.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112925645848117248/vid/avc1/2160x2700/WiyaGheJrHSWG2EH.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112925645848117248/img/qPYWKTrHjKn5vJnI.jpg", "dur": 45}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 5.06, "thread": [], "tier": "worth"}, {"id": "2113066156508766526", "url": "https://x.com/AntLingAGI/status/2113066156508766526", "text": "Excited to see Ling 3.1 Flash and the Ling 3.0 family in the SGLang-TorchTPU launch lineup! Thanks @sgl_project, Google and Meta for bringing PyTorch-native serving to TPUs—expanding hardware choice for efficient MoE inference and agentic workloads.", "name": "Ant Ling", "handle": "AntLingAGI", "avatar": "https://pbs.twimg.com/profile_images/1911666162137477120/EbzxHHzp_200x200.jpg", "likes": 18, "rts": 0, "replies": 5, "views": 700, "ts": 1792629205, "media": [], "quote": {"id": "2112948714453262363", "url": "https://x.com/sgl_project/status/2112948714453262363", "text": "Today we launch SGLang-TorchTPU, built with @Google TPU team and Meta @PyTorch team.\n\nWe’re excited to see it powering production inference at Meta!\n\nSGLang-TorchTPU is a TPU plugin for SGLang that brings:\n\n- Top open models on TPU: Muse Spark Open, GLM-5.3 Flash, Kimi K3, Ling 3.1 Flash, MiniMax H3\n- SGLang’s production features for large agentic workloads\n- Custom MegaKernel: Muse Spark Open hits 770 tok/s decode at bs=1 on InferenceX 8K/1K\n\nSGLang-TorchTPU is available now: http://github.com/sgl-project/sglang-torchtpu", "name": "SGLang", "handle": "sgl_project", "avatar": "https://pbs.twimg.com/profile_images/1923445139319685126/pyjcWZU7_200x200.jpg", "likes": 122, "rts": 19, "replies": 7, "views": 28430, "ts": 1792601204, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVKwK8YbQAAf8Yk.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.06, "thread": [], "tier": "worth"}, {"id": "2112950925614530753", "url": "https://x.com/Kling_ai/status/2112950925614530753", "text": "A little Kling magic on Magnific. ✨ #Kling4 #KlingAI", "name": "Kling AI", "handle": "Kling_ai", "avatar": "https://pbs.twimg.com/profile_images/1905183334021697536/8agjzVoq_200x200.jpg", "likes": 26, "rts": 3, "replies": 3, "views": 3263, "ts": 1792601732, "media": [], "quote": {"id": "2112940507966153008", "url": "https://x.com/magnific/status/2112940507966153008", "text": "Kling 4.0 is now on Magnific\n\nCreate scenes up to 30 seconds long, guide the action with up to 10 keyframes, and bring it together with native audio\n\nYour scene. Your direction", "name": "Magnific", "handle": "magnific", "avatar": "https://pbs.twimg.com/profile_images/2049093558435753984/fmXN11gV_200x200.png", "likes": 103, "rts": 20, "replies": 14, "views": 6893, "ts": 1792599248, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112940388113903616/vid/avc1/1280x720/wFXijyVGsNRSy5m2.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112940388113903616/vid/avc1/1920x1080/77bUwPWRfvNsPvdd.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112940388113903616/img/nAGr6sjRSp4evLWd.jpg", "dur": 43}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Video, Art & Music", "score": 5.06, "thread": [], "tier": "worth"}, {"id": "2112786086229356700", "url": "https://x.com/0xHydar/status/2112786086229356700", "text": "what stands out to me is that the tokens were burned, not held \n\n@grvt_io bought 1.1 million on the open market \n\nwith part of gross profit and sent them to the burn address\n\nmost projects talk about buybacks\n\nthis one already did the first round and took the tokens out of circulation\n\nbuybacks are intended monthly from here\n\ni like that it opened with action instead of another roadmap promise\rtbh :)", "name": "Hydareth乍得", "handle": "0xHydar", "avatar": "https://pbs.twimg.com/profile_images/1782309292298665984/PShIvufV_200x200.jpg", "likes": 378, "rts": 56, "replies": 271, "views": 8094, "ts": 1792562431, "media": [], "quote": {"id": "2112529040515146032", "url": "https://x.com/grvt_io/status/2112529040515146032", "text": "https://x.com/i/article/2112484691458904065", "name": "Grvt", "handle": "grvt_io", "avatar": "https://pbs.twimg.com/profile_images/1991661582527655936/Kn9vFGru_200x200.jpg", "likes": 542, "rts": 75, "replies": 287, "views": 257970, "ts": 1792501146, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "Money & Startups", "score": 5.05, "thread": [], "tier": "worth"}, {"id": "2112837687480623200", "url": "https://x.com/GergelyOrosz/status/2112837687480623200", "text": "How on earth did this happen:\n\nThe Indian certificate authority (CA) eMudhra had one job (well, two):\n\n1. Create secure, 384-bit private keys\n2. Store these securely and do not leak them\n\nWell, eMudhra chose private keys between 1 and 256 (the numbers!!) and called it a day. WTF", "name": "Gergely Orosz", "handle": "GergelyOrosz", "avatar": "https://pbs.twimg.com/profile_images/673095429748350976/ei5eeouV_200x200.png", "likes": 7053, "rts": 605, "replies": 211, "views": 430470, "ts": 1792574733, "media": [], "quote": {"id": "2112693364843839785", "url": "https://x.com/LinusMixson/status/2112693364843839785", "text": "I don't really understand why this would happen. It seems higher-effort than standard key generation.", "name": "Linus Mixson", "handle": "LinusMixson", "avatar": "https://pbs.twimg.com/profile_images/2050020506901131264/j6uwQ_qt_200x200.jpg", "likes": 1568, "rts": 66, "replies": 31, "views": 464385, "ts": 1792540324, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVHLazOWIAAzemC.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "Everything Else", "score": 5.05, "thread": [], "tier": "worth"}, {"id": "2112885451438649685", "url": "https://x.com/haitzu/status/2112885451438649685", "text": "My friends @axisrobotics just launched base:0x5be75e3b0aff5d1a042a5363ae36acb1d6d755ea today on Coinbase and Upbit\n\nI invited founder Chris to discuss their approach to robotics learning, especially building a globally distributed contribution model to source diverse datasets for robotics training\n\nClanker season is upon us\n\nTimestamps:\n0:00 Intro \n0:30 What is Axis Robotics? \n2:38 Are we at the GPT moment for robotics? \n4:31 Working with research labs \n7:00 How contributors create robot training data \n7:58 From Surge AI to robotics: the founding story \n10:05 Raising $12M \n12:05 The research paper: does messy sim data work? \n14:31 Is 100,000 hours enough? \n15:29 Crowdsourcing data from around the world \n17:33 Why diversity beats hours (the OpenAI call) \n18:24 Data vendor, or something bigger? \n20:30 Case study: Booster Robotics \n23:06 How Axis competes with Surge \n25:58 What's next for Axis", "name": "Jack Ai-Leung", "handle": "haitzu", "avatar": "https://pbs.twimg.com/profile_images/2109548416866947072/0gYoyH3A_200x200.jpg", "likes": 28, "rts": 5, "replies": 3, "views": 2726, "ts": 1792586121, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112885078799867904/vid/avc1/1280x720/XppZBIs0VSaKHxH-.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112885078799867904/vid/avc1/1920x1080/hrso03Ta7L5NIvvg.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112885078799867904/img/J_H8oyKVfq_P3ADt.jpg", "dur": 1628}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.05, "thread": [], "tier": "worth"}, {"id": "2113004182836027465", "url": "https://x.com/gensynai/status/2113004182836027465", "text": "\"Nobody is Paying for Good Forecasts on Purpose\"\n\nMarkets run on information, but who is being paid and is quality actually rewarded?\n\n@SplezzzK and @gab_p_andrade explore the implications in their latest research update\n\nhttps://www.gensyn.ai/research/nobody-is-paying-for-good-forecasts-on-purpose", "name": "gensyn", "handle": "gensynai", "avatar": "https://pbs.twimg.com/profile_images/1998415301478961152/kCR2lMUd_200x200.jpg", "likes": 17, "rts": 5, "replies": 1, "views": 2882, "ts": 1792614429, "media": [], "quote": null, "reply_to": null, "cat": "Research & Safety", "score": 5.05, "thread": [], "tier": "worth"}, {"id": "2113018832654676054", "url": "https://x.com/0xSolty/status/2113018832654676054", "text": "Opus 5.5 is the best planner you'll ever pay for, and the most expensive typist. one model setting splits the job:\n\n/model opusplan\n\nplan mode → Opus 5.5 thinks\nexecution → Sonnet 5.5 writes the code\nit switches by itself the moment you leave plan mode\n\nthe whole loop:\n→ Shift+Tab into plan mode\n→ Opus 5.5 reads the repo, picks the approach, writes the plan\n→ you approve the plan\n→ Sonnet 5.5 builds it in the same session, same context\n\nthe math on one long session (API prices, no cache):\nall on Opus 5.5: ~$5.60\nopusplan: ~$3.08\n\nOpus 5.5 costs $4 / $20 per million tokens, Sonnet 5.5 costs $2 / $10. about 90% of a session is execution, so most of your tokens drop to half price. on Pro/Max that means your limit lasts longer\n\nboth phases get the 1M context window on the API. if yours doesn't, use /model opusplan[1m]\n\nthe full tree\n> /model opusplan\n> plan mode: Opus 5.5 plans\n> you approve\n> execution: Sonnet 5.5 builds\n> stuck? Shift+Tab back into plan mode and Opus takes over again\n\npaste this into Claude Code ↓\n\n\"Switch me to /model opusplan. For this task: enter plan mode, read only what you need, and write a plan with the files to touch, the risks and a test checklist. Stop and wait for my approval. After I approve, implement it step by step and run the tests after each step.\"\n\n↳ http://code.claude.com/docs/en/model-config", "name": "Solty", "handle": "0xSolty", "avatar": "https://pbs.twimg.com/profile_images/2105368881640390656/MQKCHyaj_200x200.jpg", "likes": 16, "rts": 2, "replies": 5, "views": 749, "ts": 1792617922, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2113018404596527104/vid/avc1/720x900/Szb_OPqrXPsHygTs.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2113018404596527104/vid/avc1/1080x1350/tb0LI2TdKIEWIl4w.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2113018404596527104/img/dyN8kjOr_jZ3btS6.jpg", "dur": 21}], "quote": {"id": "2109018723591848410", "url": "https://x.com/0xSolty/status/2109018723591848410", "text": "https://x.com/i/article/2109000318335995904", "name": "Solty", "handle": "0xSolty", "avatar": "https://pbs.twimg.com/profile_images/2105368881640390656/MQKCHyaj_200x200.jpg", "likes": 105, "rts": 1, "replies": 5, "views": 53799, "ts": 1791664222, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.05, "thread": [], "tier": "worth"}, {"id": "2113096453694382081", "url": "https://x.com/hqmank/status/2113096453694382081", "text": "Claude now has its own personal AI agent: Claude Duet.\n\nPowered by Opus 5.5, it can:\n- Proactively flag what needs your attention.\n- Keep working while you're away.\n- Use your existing Claude memory, skills, and connected apps.\n- Ask for approval before sensitive actions.\n\nMy take: Grok Bot, OpenAI Dots, and now Claude Duet are all moving toward AI agents that work for you without constant prompting.\n\nA few things to know:\n- US Claude Pro and Max users can join the waitlist.\n- Background tasks use your existing Claude limits.\n\nWaitlist: https://claude.com/product/claude-duet", "name": "Kai", "handle": "hqmank", "avatar": "https://pbs.twimg.com/profile_images/2001227557765832707/XG7mxw62_200x200.jpg", "likes": 11, "rts": 0, "replies": 7, "views": 1016, "ts": 1792636428, "media": [], "quote": {"id": "2112984664256241837", "url": "https://x.com/claudeai/status/2112984664256241837", "text": "We’re opening a research preview of Claude Duet, a new app where Claude works as a proactive agent.\n\nIt comes to you with what needs your attention, completes tasks you ask of it, keeps working when you step away, and checks with you before it acts on your behalf.", "name": "Claude", "handle": "claudeai", "avatar": "https://pbs.twimg.com/profile_images/1950950107937185792/QOfEjFoJ_200x200.jpg", "likes": 43209, "rts": 3270, "replies": 1714, "views": 5525351, "ts": 1792609775, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112982862186106880/vid/avc1/640x360/L7zosiEUW76tqYr-.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112982862186106880/vid/avc1/640x360/L7zosiEUW76tqYr-.mp4?tag=29", "thumb": "https://pbs.twimg.com/media/HVLUnMDWsAAn7Pw.png", "dur": 100}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.05, "thread": [], "tier": "worth"}, {"id": "2112922437515878824", "url": "https://x.com/PrunaAI/status/2112922437515878824", "text": "Munich, join us for Hacktoberfest with @MLHacks ! \n\nWe're hosting a casual meetup at the Pruna office on October 29!\n\nCome grab a pizza, have a drink, meet other developers, and chat about open source, side projects, or whatever you're building.\n\nNo talks or pitches, just a relaxed evening with the local community.\n\n📍 Pruna office, Munich  \n📅 October 29, 6–9 PM\n\nHope to see you there! \n\n👉 Sign up: https://events.mlh.com/events/15374-hacktoberfest-meetup-munich-x-pruna-ai", "name": "Pruna AI", "handle": "PrunaAI", "avatar": "https://pbs.twimg.com/profile_images/1819385083129720832/qv8GhECE_200x200.jpg", "likes": 22, "rts": 6, "replies": 2, "views": 545, "ts": 1792594939, "media": [], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.05, "thread": [], "tier": "worth"}, {"id": "2112793815765369251", "url": "https://x.com/TinaFabe/status/2112793815765369251", "text": "I have noticed something recently.\n\nI have changed abit in the way I speak, I'm now soft spoken.\n\nIt's sort of weird to me but I really don't have the energy to shout or talk aloud these days.\n\nAgain, being around chaotic people drains my energy fast, so I avoid such spaces.\n\nBut at the same time, I miss enjoying spaces, I bet life got more serious.", "name": "Tina 🥺❤️", "handle": "TinaFabe", "avatar": "https://pbs.twimg.com/profile_images/2057848169187151872/3HQ6BYAB_200x200.jpg", "likes": 32, "rts": 5, "replies": 9, "views": 448, "ts": 1792564274, "media": [], "quote": {"id": "2112787308332130703", "url": "https://x.com/TinaFabe/status/2112787308332130703", "text": "I have been thinking about something interesting about prediction markets.\n\nDoes a market need thousands of traders and millions of dollars in volume to be valuable?\n\nI don't think so.\n\nImagine you are a fan of a particular anime, and your community is debating which character will survive the next episode.\n\nOr you are in a music community where everyone is predicting which artist will release an album before the end of the year.\n\nThese questions might not interest the entire internet, but they matter to the people having those conversations.\n\nThe problem is that traditional prediction market platforms tend to focus on events with broad appeal. Smaller, more specific questions can struggle to get listed because they may not attract enough trading activity.\n\nThis is where @xomarket takes a different approach.\n\nXO's Convictions allow users to create markets around questions that interest them, starting from $10.\n\nYou don't need to wait for a platform to decide that your question is popular enough to deserve a market.\n\n➜ A gaming community can create markets around tournaments.\n\n➜ Music fans can explore predictions about upcoming releases.\n\n➜ Crypto communities can trade on specific events they follow.\n\n➜ Content creators can turn questions their audiences already debate into markets.\n\nNot every Conviction will become popular, and not every market will attract enough liquidity to support active trading.\n\nBut that's part of the idea behind XO 2.0.\n\nSome markets may remain small, serving a community of people who genuinely care about the outcome. Others may attract wider attention and grow into larger Prediction Markets.\n\nA market doesn't have to interest everyone to be valuable to someone.\n\nI think giving niche communities the freedom to create their own markets is one of the more interesting ideas in prediction markets.\n\nWhat small or unusual topic would you create a market around?\n\nhttp://s.kaito.ai/Zb0bF3i", "name": "Tina 🥺❤️", "handle": "TinaFabe", "avatar": "https://pbs.twimg.com/profile_images/2057848169187151872/3HQ6BYAB_200x200.jpg", "likes": 38, "rts": 11, "replies": 10, "views": 804, "ts": 1792562722, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVIg2MEXYAA1mEC.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Video, Art & Music", "score": 5.04, "thread": [], "tier": "worth"}, {"id": "2112843246099460464", "url": "https://x.com/Mikadzyki_NFT/status/2112843246099460464", "text": "this is a whole other f*cking level\n\ngrok bot just wiped out the best salespeople in the industry\n\none guy with no team of his own and no background in deals is closing enterprise contracts better than departments with twenty years behind them. all the work is done by a system he spun up on a $300 subscription\n\non september 3 xAI revealed something unexpected - the heaviest load on the neural net comes not from engineers but from sales. and he squeezed everything out of it\n\nhe put together 3 agents, each with its own role:\n\n- researching target companies overnight\n\n- preparing personalized outreach\n\n- running the call in real time\n\nwhile he sleeps, the first one goes through the list of companies, watches their webinars and podcasts and pulls hooks for each deal out of what people there talk about\n\nby breakfast the second lays out finished drafts of emails and LinkedIn messages for every account, but nothing goes out without his nod\n\nbefore, prepping for a single call ate an evening of research plus a morning of writing. now everything is waiting by the first cup of coffee\n\nbut what really got him was the very first meeting\n\nwhile the client was walking through their problems, the third one listened and reshaped the deck on the fly to fit everything he said\n\nthe slide with next steps was done before they said goodbye. the follow-up that takes everyone else an hour is now born right inside the conversation\n\nwhile a live team pushes through five calls a day, this trio runs 60 accounts in parallel and closes each one with a ready slide\n\nin the first week he ran 40 meetings and closed a $120,000 deal right on the call where the deck assembled itself\n\none person now replaces an entire presales department, an analyst and an assistant, while his competitors are still prepping a single call for the morning", "name": "Mikadzyki🌙", "handle": "Mikadzyki_NFT", "avatar": "https://pbs.twimg.com/profile_images/2094301804611633152/1H8uVIE__200x200.jpg", "likes": 30, "rts": 3, "replies": 8, "views": 1006, "ts": 1792576059, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112843054700777472/vid/avc1/1280x720/07KrMgl1f1EZ3KVi.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112843054700777472/vid/avc1/1920x1080/FB37Qf6CMI4NPsEA.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112843054700777472/img/k9VSOJlSIv1WY-sa.jpg", "dur": 45}], "quote": {"id": "2112830872072151250", "url": "https://x.com/hammertime_one/status/2112830872072151250", "text": "The most common Grok Bot mistake: one bot, five jobs.\n\nResearcher, strategist, writer, editor, publisher. All in one.\n\n7 guides say the same fix: one job per bot, one limit per bot. The article shows how they build it. https://x.com/i/article/2112816238569394176", "name": "hammertime", "handle": "hammertime_one", "avatar": "https://pbs.twimg.com/profile_images/2105980393258135552/MN4JaKHX_200x200.jpg", "likes": 23, "rts": 3, "replies": 6, "views": 3075, "ts": 1792573109, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.04, "thread": [], "tier": "worth"}, {"id": "2112850691077124441", "url": "https://x.com/MistaGreat_1/status/2112850691077124441", "text": "How far you think we can go with gaming but with AI tho? 🤔 \n\nSomeone's creating his dream online MOBA game using Opus\n\nIt’s a 5v5 multiplayer MOBA with:\n\n⚔️ Hero-based combat\n🔥 Epic abilities and team fights\n🎮 PC, Mac and mobile support\n🕹️ Controller support\n\nThe dev has spent 500+ hours building games with AI and finally started working on his dream project.\n\nIt’s still early, and he’s looking for players to test it.\n\nWould you try an AI-built MOBA?\n\nS҉A҉Y҉ ҉L҉E҉S҉S҉ ✌🏽D҉O҉ ҉M҉O҉R҉E҉", "name": "MistaGreat 🐐", "handle": "MistaGreat_1", "avatar": "https://pbs.twimg.com/profile_images/2083829506112880640/vXIWF0mo_200x200.jpg", "likes": 24, "rts": 2, "replies": 12, "views": 620, "ts": 1792577834, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112850561791881216/vid/avc1/640x360/j-nHJnycbYha4Plr.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112850561791881216/vid/avc1/1280x720/3wXidTdh3JoUVM1y.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112850561791881216/img/cmk1tlvRK0F25rPC.jpg", "dur": 53}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.04, "thread": [], "tier": "worth"}, {"id": "2112940533790425437", "url": "https://x.com/AmitShah/status/2112940533790425437", "text": "पंजाब के गुरदासपुर, संगरूर व मानसा में नशे के खिलाफ लड़ते हुए अपना जीवन गँवाने वाले लोगों के परिजनों से कल मिला। इन परिवारों पर जो बीत रही है, उसे शब्दों में नहीं कहा जा सकता। 31 दिसंबर 2029 से पहले हम पंजाब और पूरे देश से इस नशे के कारोबार को समाप्त करके रहेंगे।\n\nਪੰਜਾਬ ਦੇ ਗੁਰਦਾਸਪੁਰ, ਸੰਗਰੂਰ ਅਤੇ ਮਾਨਸਾ ਵਿੱਚ ਨਸ਼ੇ ਖਿਲਾਫ਼ ਲੜਦਿਆਂ ਆਪਣੀ ਜਾਨ ਗੁਆਉਣ ਵਾਲੇ ਲੋਕਾਂ ਦੇ ਪਰਿਵਾਰਾਂ ਨੂੰ ਕੱਲ੍ਹ ਮਿਲਿਆ। ਇਨ੍ਹਾਂ ਪਰਿਵਾਰਾਂ ਉੱਤੇ ਜੋ ਬੀਤ ਰਹੀ ਹੈ, ਉਸਨੂੰ ਸ਼ਬਦਾਂ ਵਿੱਚ ਬਿਆਨ ਨਹੀਂ ਕੀਤਾ ਜਾ ਸਕਦਾ। 31 ਦਸੰਬਰ 2029 ਤੋਂ ਪਹਿਲਾਂ ਅਸੀਂ ਪੰਜਾਬ ਅਤੇ ਪੂਰੇ ਦੇਸ਼ ਵਿੱਚੋਂ ਇਸ ਨਸ਼ੇ ਦੇ ਕਾਰੋਬਾਰ ਨੂੰ ਖ਼ਤਮ ਕਰਕੇ ਰਹਾਂਗੇ।", "name": "Amit Shah", "handle": "AmitShah", "avatar": "https://pbs.twimg.com/profile_images/2054423554737983489/dhxe-t8m_200x200.jpg", "likes": 4270, "rts": 680, "replies": 121, "views": 97088, "ts": 1792599254, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112939391488507904/vid/avc1/1280x720/rq5EQZIslwJw01wY.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112939391488507904/vid/avc1/1920x1080/xvtuFzPSovVw5ET-.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112939391488507904/img/xiZlk_HvaPF3pGq0.jpg", "dur": 157}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 5.04, "thread": [], "tier": "worth"}, {"id": "2112941106518257998", "url": "https://x.com/noclipepe/status/2112941106518257998", "text": "WE HAVE LIGHTNING McQUEEN AT HOME:\n\nThe task via http://aimlapi.com: recreate McQueen as a 3D model with animated eyes.\n\nGPT‑6.1 Sol → 2.58M tokens · ~$0.78\nGPT‑6 Luna → 2.11M tokens · ~$0.04\n\nSol brought the racing body, decals and smug expression.\nLuna brought his cousin from Rocket League 😭\n\n18× the estimated cost. Is this finally a gap worth paying for?", "name": "noclipepe", "handle": "noclipepe", "avatar": "https://pbs.twimg.com/profile_images/2079860441333846016/fEbqKdNE_200x200.jpg", "likes": 20, "rts": 0, "replies": 10, "views": 549, "ts": 1792599390, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112940634449326080/vid/avc1/720x960/pfyd9_MbJEF93vcY.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112940634449326080/vid/avc1/1080x1440/TLiRyTzdabY4oEZh.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112940634449326080/img/eqaYA-Ty4tfk8h6b.jpg", "dur": 31}], "quote": {"id": "2102572756353061250", "url": "https://x.com/noclipepe/status/2102572756353061250", "text": "https://x.com/i/article/2102549918913040384", "name": "noclipepe", "handle": "noclipepe", "avatar": "https://pbs.twimg.com/profile_images/2079860441333846016/fEbqKdNE_200x200.jpg", "likes": 61, "rts": 6, "replies": 6, "views": 491022, "ts": 1790127383, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.04, "thread": [], "tier": "worth"}, {"id": "2113039393493749925", "url": "https://x.com/wwardenn/status/2113039393493749925", "text": "THIS FREE AI SKILL MAKES CLAUDE CODE DESIGN WEBSITES LIKE A CREATIVE STUDIO\n\nMost AI-generated websites follow the same formula: massive headline, three feature cards, generic gradients, and a layout that looks like every other startup landing page.\n\nA developer released /awwwards, an open-source skill that changes how AI coding agents approach web design.\n\nInstead of jumping straight into code, the agent follows an actual creative production process.\n\nHere's how it works:\n\nDevelops multiple visual concepts before choosing a direction\nDefines typography, colors, layout, and art direction\nCreates a design document before implementation\nBuilds the website using the selected visual system\nCaptures real desktop and mobile screenshots\nRuns visual, accessibility, and performance checks\nUses an independent review process to identify weak spots\n\nThe most interesting part is the quality-control loop.\n\nThe system doesn't treat working code as proof of good design.\n\nIt evaluates the actual rendered website against a structured rubric covering design, usability, creativity, and content.\n\nThe project targets an 8/10 score across those categories, although that's an internal evaluation target rather than an independent quality guarantee.\n\nFor marketing teams, this solves a problem that better prompts alone rarely fix.\n\nAI can generate landing pages incredibly quickly, but a technically functional website can still have weak positioning, poor visual hierarchy, and generic creative direction.\n\nAdding concept development and independent review forces the workflow to address those problems before the page is considered finished.\n\nThe skill also requires browser testing and multiple iterations, so it isn't a one-click replacement for a designer.\n\nBut the architecture is worth studying.\n\nAs AI makes execution cheaper, the advantage increasingly comes from the quality of the creative process surrounding it.\n\nThe next improvement in AI-generated websites may come from better art direction and stronger evaluation systems rather than another coding model.\n\nrepo ↓", "name": "Warden", "handle": "wwardenn", "avatar": "https://pbs.twimg.com/profile_images/2108469454254333952/W8cX8Sej_200x200.jpg", "likes": 19, "rts": 0, "replies": 5, "views": 515, "ts": 1792622824, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2113039361558114304/vid/avc1/640x360/hKXPyiwWtGH11-Vp.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2113039361558114304/vid/avc1/1280x720/OMM_YpWbaW7V7SMv.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2113039361558114304/img/FS-EhRH0k1Qc8ss2.jpg", "dur": 31}], "quote": {"id": "2110410080940073193", "url": "https://x.com/wwardenn/status/2110410080940073193", "text": "https://x.com/i/article/2110374398028914688", "name": "Warden", "handle": "wwardenn", "avatar": "https://pbs.twimg.com/profile_images/2108469454254333952/W8cX8Sej_200x200.jpg", "likes": 68, "rts": 3, "replies": 13, "views": 13189, "ts": 1791995947, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.04, "thread": [], "tier": "worth"}, {"id": "2112964981021110306", "url": "https://x.com/DesignArena/status/2112964981021110306", "text": "Kling 4.0 by @Kling_ai is now available on Design Arena!\n\nKling 4.0 brings major improvements in visual realism, creative control, and narrative completeness, alongside enhanced audiovisual quality, multi-keyframe generation, lip-sync, and text generation. Kling 4.0 Flash offers faster generation with reliable quality for frequent video creation.\n\nCongrats to the @Kling_ai team on the launch!", "name": "DesignArena", "handle": "DesignArena", "avatar": "https://pbs.twimg.com/profile_images/1988401101797027844/yZ6rC4I7_200x200.jpg", "likes": 22, "rts": 3, "replies": 3, "views": 1190, "ts": 1792605083, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVLCTrobIAAksZ5.jpg?name=orig"}], "quote": {"id": "2112946255257084260", "url": "https://x.com/Kling_ai/status/2112946255257084260", "text": "KLING 4.0 API — Officially Rolling Out Now\n\nIntegrate Kling 4.0 into your products and workflows. Let’s build. 🚀 #Kling4 #KlingAI", "name": "Kling AI", "handle": "Kling_ai", "avatar": "https://pbs.twimg.com/profile_images/1905183334021697536/8agjzVoq_200x200.jpg", "likes": 115, "rts": 13, "replies": 19, "views": 7768, "ts": 1792600618, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVKxZ72XUAA051O.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.04, "thread": [], "tier": "worth"}, {"id": "2112917859147911623", "url": "https://x.com/Nazik2053/status/2112917859147911623", "text": "GEMINI SHOULD REMEMBER THE PROMISE YOU FORGOT YOU MADE\n\n\"I'll send comments before the call.\"\n\nYou wrote it, meant it, then buried it under the next twenty messages. That is the kind of thing I want a second brain to bring back before the meeting\n\nMy Gemini 4 guide builds around that job: keep the source, connect it to the person and project, then prepare something useful for you to review\n\nThe setup has three parts:\n\n-> Memory: a Drive folder called Brain. Originals stay in raw/. People and projects get their own docs. INDEX points the agent to the relevant context\n\n-> Routines: matching mail gets filed; weekdays at 5 PM, attention gets refreshed from sent mail and calendar activity; at 7:30 AM, one morning page brings together linked facts, marked guesses, drafts and open questions. Sunday recall surfaces changed plans and forgotten decisions\n\n-> Output: three reusable skills turn a note into a plan, a thread into a reply, or an idea into a post. Everything lands in out/ for review\n\nThe part that makes it personal is voice: rules drawn from sentences you actually wrote. Before drafting, the agent reads those examples. Your corrections go into rules, which it reads before the next task\n\nFor the follow-up example, the target is concrete: the original promise stays linked to its project, the current meeting details get checked at the source, and a reply draft waits for your yes\n\nTry one small task first:\n\n\"Find one follow-up I promised in this email thread. Check the current details against the source. Read Brain/voice and Brain/rules, draft the reply in Brain/out, and link the original message. Send nothing.\"\n\nThe animation maps the workflow. You'll need Task access and connected apps; some steps may pause for confirmation. Test one project before trusting a wider schedule\n\nThe article below has all seven steps, the four routines and the combined setup prompt. Start with one promise worth keeping.", "name": "Nazar", "handle": "Nazik2053", "avatar": "https://pbs.twimg.com/profile_images/2081786582852374528/U40IQu7b_200x200.jpg", "likes": 18, "rts": 3, "replies": 8, "views": 680, "ts": 1792593848, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112807526920015872/vid/avc1/720x1018/fWcUqIOTYIT66d5s.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112807526920015872/vid/avc1/1080x1528/gOrMFEsNPSA-wcDk.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112807526920015872/img/q0EwDNIDJO_RL0SH.jpg", "dur": 20}], "quote": {"id": "2110757128050745432", "url": "https://x.com/Nazik2053/status/2110757128050745432", "text": "https://x.com/i/article/2110633972719812608", "name": "Nazar", "handle": "Nazik2053", "avatar": "https://pbs.twimg.com/profile_images/2081786582852374528/U40IQu7b_200x200.jpg", "likes": 9, "rts": 4, "replies": 1, "views": 8392, "ts": 1792078689, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.03, "thread": [], "tier": "worth"}, {"id": "2113017712788013501", "url": "https://x.com/0xSpikez/status/2113017712788013501", "text": "961.6 tokens/s on a 27B model, one request. That's EAGLE-4 on Qwen3.8-27B, BF16, 4x B300.\n\nHow speculative decoding gets there:\n\n> a small drafter model guesses the next few tokens\n> the big model checks all of them in one pass\n> every correct guess is free speed, and the output distribution stays the same\n\nEAGLE-4 adapts the drafter to batch size and hardware. Their paper reports 1.70x over DFlash 2 at 512 concurrent requests. If you serve real traffic, that number matters more than the single-request one.\n\nOpen source: http://github.com/eagle-hq/EAGLE-4\n\nbookmark this if you self-host", "name": "Spikez 99.9%", "handle": "0xSpikez", "avatar": "https://pbs.twimg.com/profile_images/2096992378959826944/rCY0UFsk_200x200.jpg", "likes": 18, "rts": 1, "replies": 5, "views": 480, "ts": 1792617655, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2113017623906594816/vid/avc1/640x360/Oiet5HXQZlkI9Fgt.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2113017623906594816/vid/avc1/1280x720/4cvPIPmIpxohez2W.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2113017623906594816/img/8Nx9O0q6WOZHeX2J.jpg", "dur": 47}], "quote": {"id": "2112875220155674923", "url": "https://x.com/0xSpikez/status/2112875220155674923", "text": "EAGLE-4: 961 tokens/s by squeezing more out of the GPUs you already own\n\nJensen:", "name": "Spikez 99.9%", "handle": "0xSpikez", "avatar": "https://pbs.twimg.com/profile_images/2096992378959826944/rCY0UFsk_200x200.jpg", "likes": 20, "rts": 0, "replies": 4, "views": 967, "ts": 1792583682, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112875162248830976/vid/avc1/640x360/s4A2y9f8DBlV7qwJ.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112875162248830976/vid/avc1/1280x720/fBblpdKEaMgMNj82.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112875162248830976/img/AAcKaNSpfmQvkfQ8.jpg", "dur": 33}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.03, "thread": [], "tier": "worth"}, {"id": "2112952055002234906", "url": "https://x.com/netflix/status/2112952055002234906", "text": "Talia’s cyberware is too preem.\n\nCyberpunk: Edgerunners 2 is NOW PLAYING", "name": "Netflix", "handle": "netflix", "avatar": "https://pbs.twimg.com/profile_images/1996301804053868544/Xrwvbe1q_200x200.jpg", "likes": 4960, "rts": 360, "replies": 49, "views": 750880, "ts": 1792602001, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112946826328338432/vid/avc1/1280x720/aIO7_hFEb-hlUCsm.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112946826328338432/vid/avc1/1920x1080/sbZ_Dm6ZG-UEM0mz.mp4?tag=16", "thumb": "https://pbs.twimg.com/media/HVKyAyIXEAAp56_.png", "dur": 57}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 5.03, "thread": [], "tier": "worth"}, {"id": "2112812916110205319", "url": "https://x.com/Alex_tra_memory/status/2112812916110205319", "text": "saw that Underdog-Bark-3.0 already has a coreml encoder. got curious how the full pipeline would look in coreml and some of my own encoder touches. \n\nresulting in  1 h of audio in 13 s (276× RTFx) and LibriSpeech test-other 4.96 % WER @ 140× on M5 Pro .\n\nhf repo coming soon.", "name": "Alex", "handle": "Alex_tra_memory", "avatar": "https://pbs.twimg.com/profile_images/2112779475347804160/MNJ06Hba_200x200.jpg", "likes": 38, "rts": 4, "replies": 4, "views": 1549, "ts": 1792568828, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112809945338916864/vid/avc1/1538x720/FpoKblmkOVWOEN45.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112809945338916864/vid/avc1/2702x1264/Vpp4Bjah7Sx65fw7.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112809945338916864/img/ydnaTOs-QikVwEC0.jpg", "dur": 16}], "quote": {"id": "2112733007484518470", "url": "https://x.com/UnderdogAI/status/2112733007484518470", "text": "Today we’re releasing Underdog Bark 3.0, the #1 frontier speech model\n\nIt's a tiny 163 MB download as accurate as NVIDIA’s Parakeet (15x bigger). It beats OpenAI's Whisper large-v3 (57x bigger)\n\nIt's fast- transcribes 1 min of audio in <0.25s on a Macbook. On recorded meetings (AMI), Bark 3.0 gets 7.82% of words wrong. Parakeet gets 9.42%. OpenAI's Whisper large-v3 gets 13.63% error rate\n\nBark runs on both your Laptop & Phone. It’s free and open source under CC-BY 4.0\n\nTry private on-device meeting notes & dictation, powered by Bark, in Underdog today: http://underdog.ai/bark", "name": "Underdog AI", "handle": "UnderdogAI", "avatar": "https://pbs.twimg.com/profile_images/2105061490667704320/r6kSmuDf_200x200.jpg", "likes": 4140, "rts": 253, "replies": 212, "views": 198809, "ts": 1792549776, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVHunLfa4AAeL2Y.jpg?name=orig"}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.02, "thread": [], "tier": "worth"}, {"id": "2112929944447721673", "url": "https://x.com/0xOrionVega/status/2112929944447721673", "text": "you can call me crazy but.. Grok Bot + Jev WON'T make you a MILLIONAIRE\n\none BORING line will\n\nidea → grok bot → jev → execute → $$$ is missing the ONLY step that keeps the money\n\njev picks the best model for every call. it NEVER asks if the trade is worth taking\n\nso my chain has a GATE before anything executes:\n\ndraft the idea → grok bot\npick the model → jev, with a confidence\nkill what fees eat → plain python\nsize it → quarter Kelly, never above 2%\nconfidence under 0.80 → ask_human. that's me\nexecute → grok bot, only after all 4 say yes\n\nthe line:\n\nnet edge = gross edge - fees - half spread - slippage\n\njev was 94% SURE on a 9bp idea. costs were 11bp. a -2bp LOSER it would have fired with FULL confidence\n\nthe router makes it FAST. the gate makes it MONEY\n\nwhat would YOU let it execute without asking?", "name": "Orion", "handle": "0xOrionVega", "avatar": "https://pbs.twimg.com/profile_images/2083267605968683008/lzxHbmpL_200x200.jpg", "likes": 23, "rts": 3, "replies": 4, "views": 872, "ts": 1792596729, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112929663068557312/vid/avc1/720x900/Z4j98p0cEWIgCojm.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112929663068557312/vid/avc1/1080x1350/I0UfhaJY64d4z7fr.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112929663068557312/img/YHeV0yY1kYcyTaPd.jpg", "dur": 22}], "quote": {"id": "2110731912176095700", "url": "https://x.com/velesxbt/status/2110731912176095700", "text": "how do you know a trading strategy still works?\n\nyou don’t. unless you test it.\n\nthis guide turns your AI into a research desk that does it for you: real data, real backtests, stress tests, and a path to your broker https://x.com/i/article/2110377833579061248", "name": "Veles", "handle": "velesxbt", "avatar": "https://pbs.twimg.com/profile_images/2109226539799703552/gTsHS1Ht_200x200.jpg", "likes": 92, "rts": 17, "replies": 13, "views": 248923, "ts": 1792072678, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.02, "thread": [], "tier": "worth"}, {"id": "2112946829142671844", "url": "https://x.com/robiartec/status/2112946829142671844", "text": "> ask your agent to sign up for a tool\n> it needs an email\n> you give it yours\n> now it can read your bank alerts\n> and your landlord's emails\n> and every receipt since 2014\n\nagentmail gives it its own inbox. please", "name": "rob.", "handle": "robiartec", "avatar": "https://pbs.twimg.com/profile_images/2107044216622788608/u-q8hY-9_200x200.jpg", "likes": 14, "rts": 4, "replies": 6, "views": 1008, "ts": 1792600755, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112946779389874177/vid/avc1/832x464/gCqz2AzdbTgEQA35.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112946779389874177/vid/avc1/832x464/gCqz2AzdbTgEQA35.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112946779389874177/img/uN9oexOIt__W8k4f.jpg", "dur": 13}], "quote": {"id": "2112936820900331976", "url": "https://x.com/michaelhyunkim/status/2112936820900331976", "text": "Today, @agentmail has processed over 1 Billion emails.\n\nA year ago, we processed under 20 million.\n\nSo we figured it was time for AgentMail to grow up a little too :)", "name": "Michael Kim", "handle": "michaelhyunkim", "avatar": "https://pbs.twimg.com/profile_images/2064613097982345216/RtVvP-41_200x200.jpg", "likes": 479, "rts": 34, "replies": 181, "views": 115778, "ts": 1792598369, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112936749408378880/vid/avc1/640x360/WReJSxJlX7wwQ-KR.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112936749408378880/vid/avc1/1280x720/Q3sC28-K20Oaxxiv.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112936749408378880/img/3NlAnuPst12Eg6dG.jpg", "dur": 40}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.02, "thread": [], "tier": "worth"}, {"id": "2113109032324276628", "url": "https://x.com/karanC_12/status/2113109032324276628", "text": "🚨Opus 5.5 got nerfed?\n\nSame AK-47 3D benchmark. Same prompt. 18 days apart.\n\nOld Opus 5.5 vs. Opus 5.5 today.\n\nSpot the difference.", "name": "KC", "handle": "karanC_12", "avatar": "https://pbs.twimg.com/profile_images/2099414876355735552/XpwRExm6_200x200.jpg", "likes": 11, "rts": 1, "replies": 4, "views": 1336, "ts": 1792639427, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2113084079922888704/vid/avc1/720x720/3WSHBDvo4Icv9l9H.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2113084079922888704/vid/avc1/1080x1080/zBSQw0pHuFKmkIbS.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2113084079922888704/img/Qg13k_6KzCmH_6lJ.jpg", "dur": 12}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.02, "thread": [], "tier": "worth"}, {"id": "2112947597338140687", "url": "https://x.com/duttasomrattwt/status/2112947597338140687", "text": "we are in the era of \nshipping sloppy Claude coded launch videos\neven bigger companies are doing it\ncant fight against the trend i guess", "name": "Somrat Dutta", "handle": "duttasomrattwt", "avatar": "https://pbs.twimg.com/profile_images/1982188160013447169/2EXmxpkd_200x200.jpg", "likes": 30, "rts": 0, "replies": 4, "views": 2972, "ts": 1792600938, "media": [], "quote": {"id": "2112335838801731970", "url": "https://x.com/WisprFlow/status/2112335838801731970", "text": "it's here (finally) 🌑", "name": "Wispr Flow", "handle": "WisprFlow", "avatar": "https://pbs.twimg.com/profile_images/1899840130237730816/mOZdb0UE_200x200.png", "likes": 769, "rts": 18, "replies": 141, "views": 341366, "ts": 1792455083, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112332775072366592/vid/avc1/960x720/4JRBjTsqOmgFBwMP.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112332775072366592/vid/avc1/1440x1080/oIZiOou8FSbtRe92.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112332775072366592/img/4ACcyf__7RGahspb.jpg", "dur": 40}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.02, "thread": [], "tier": "worth"}, {"id": "2112960150411604416", "url": "https://x.com/88n77n/status/2112960150411604416", "text": "THIS SHOULD BE ILLEGAL: GROK CAN NOW READ EVERY APP ON YOUR DISK. HERE ARE 12 THINGS TO MAKE IT FIND\n\neveryone's using this to get free Photoshop. that's the least interesting part\n\nthe money is in the boring jobs nobody wants\n\na company lost the source for an old internal tool and needs it moved to something modern. two apps refuse to talk to each other and a team needs them to. bug bounty programs pay people to find what's broken inside apps they're allowed to test\n\nall of it starts with the same move. read the app, write down how it behaves, prove it\n\nthat's what REA gives Grok Build. you ask about a program, it comes back with the file, the function, and what it couldn't prove\n\nit won't turn you into a security researcher overnight. it just kills the part that used to take weeks in a disassembler\n\n12 starting jobs in the clip\n\nwhich one would you charge for first?", "name": "88n77", "handle": "88n77n", "avatar": "https://pbs.twimg.com/profile_images/2103898548286730240/MxLlo5nw_200x200.jpg", "likes": 20, "rts": 2, "replies": 5, "views": 448, "ts": 1792603931, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112935863684300800/vid/avc1/720x900/sB7X4TrIGsYU_iUr.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112935863684300800/vid/avc1/1080x1350/LTE9-A7oJtL568Rp.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112935863684300800/img/cRCXYDkJ3r_gsAta.jpg", "dur": 15}], "quote": {"id": "2112199688694681656", "url": "https://x.com/88n77n/status/2112199688694681656", "text": "https://x.com/i/article/2111842592891498496", "name": "88n77", "handle": "88n77n", "avatar": "https://pbs.twimg.com/profile_images/2103898548286730240/MxLlo5nw_200x200.jpg", "likes": 11, "rts": 3, "replies": 4, "views": 2124, "ts": 1792422623, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.02, "thread": [], "tier": "worth"}, {"id": "2112876556767150082", "url": "https://x.com/witcheer/status/2112876556767150082", "text": "the Hermes plugin catalog has passed 750 plugins.\n\nmemory, voice, messaging, browsing and more, built by the community.\n\nwhich one should I test and showcase?", "name": "witcheer", "handle": "witcheer", "avatar": "https://pbs.twimg.com/profile_images/2057938653217701888/2uzVsJ5p_200x200.jpg", "likes": 36, "rts": 0, "replies": 6, "views": 2675, "ts": 1792584001, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112800621644374016/vid/avc1/1280x720/rA9fmM1WV21q7hbt.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112800621644374016/vid/avc1/1920x1080/A12FNnCCOS79838t.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112800621644374016/img/8E8AdvJryMi9H0Uf.jpg", "dur": 34}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.02, "thread": [], "tier": "worth"}, {"id": "2112816659161362653", "url": "https://x.com/ayyoweb3/status/2112816659161362653", "text": "payout code retries. that's how people get paid twice.\n\nnetworks time out. workers crash. ai agents repeat actions. every retry can send the same payment again, and nobody notices until the money is gone.\n\nso i built once, a usdc payout vault on @arc that pays every payout exactly once, even when your code asks twice.\n\nhow it works\nevery payout has an intent id. the contract pays each intent at most once, and the total paid can never pass the budget you approved.\n→ send the same payout again? refused onchain with DUPLICATE_INTENT.\n→ try to spend more than the budget? refused with OVER_BUDGET.\nthe rule lives in the contract, so no buggy script or rogue bot can break it.\n\nlive on arc mainnet\nanyone can connect a wallet and create their own vault. there are no admin keys, and no one else can touch your funds. in the demo, the same payout is sent 5 times: 1 is paid, 4 are refused onchain, each with a real transaction hash. close out sends the unused funds back to the owner.\n\nbuilt with arc studio\ni built the vault contract, the factory, the tests (42, including a 5-retry storm and a fuzz test proving the total paid never passes the budget) and the react app in arc studio. then i deployed the same contract to arc mainnet myself and verified it on the explorer.\n\nwho it's for\n• teams and daos paying contributors, payroll or bounties\n• ai agent builders whose agents must never pay twice\n• payroll, bounty and grant platforms\n• marketplaces and gig platforms releasing payments\n• payout services sending usdc in bulk\n\nwhat's next\npayer keys for agents, recurring payouts, batch payouts, cross-chain payouts with circle cctp, and a developer sdk so any app can pay through once.\n\ntry it 👇\n🔗 http://once-arc.vercel.app\n💻 http://github.com/london160771/Once\n\nsubmitted to arc microgrants on @DoraHacks.\n\npay exactly once.", "name": "ayo (building arc)", "handle": "ayyoweb3", "avatar": "https://pbs.twimg.com/profile_images/2109733838456823808/xsOjbSxS_200x200.jpg", "likes": 21, "rts": 7, "replies": 7, "views": 711, "ts": 1792569720, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112789791196549121/vid/avc1/1280x720/e6qgsyWYkZIS1Oak.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112789791196549121/vid/avc1/1920x1080/yxRFByLswLMUoG-K.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112789791196549121/img/Y346tpQrHvDg8Dk8.jpg", "dur": 166}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.01, "thread": [], "tier": "worth"}, {"id": "2112878634746986947", "url": "https://x.com/emilkowalski/status/2112878634746986947", "text": "This is my last week at Linear.\n\nIt was a privilege to work with such a talented team for the last two years.\n\nHere are a few of my favorite things I helped create during my time here:", "name": "Emil Kowalski", "handle": "emilkowalski", "avatar": "https://pbs.twimg.com/profile_images/1469017066795679751/CjEOyirb_200x200.jpg", "likes": 6577, "rts": 111, "replies": 253, "views": 202532, "ts": 1792584496, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112878203568001024/vid/avc1/1260x720/ddf2WP4cmVVzxms2.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112878203568001024/vid/avc1/3332x1902/fuSPfuwDsREhwGgQ.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112878203568001024/img/TJSiNNIigsbO-9UH.jpg", "dur": 67}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 5.01, "thread": [], "tier": "worth"}, {"id": "2112861479456170355", "url": "https://x.com/blazejkustra_/status/2112861479456170355", "text": "A few months ago running parallel agents with multiple simulators was a nightmare\n\nagent A boots a sim, agent B grabs the same one\n\nA taps a button, B reinstalls the app, both think their test failed\n\nwe almost built device locking into Argent to fix it. here’s why we didn’t 🧵", "name": "Błażej Kustra", "handle": "blazejkustra_", "avatar": "https://pbs.twimg.com/profile_images/2006830913481498624/DAbrO5rP_200x200.jpg", "likes": 33, "rts": 4, "replies": 2, "views": 1521, "ts": 1792580406, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112847143245377536/vid/avc1/1280x720/DpD6fiknfrRlQgu9.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112847143245377536/vid/avc1/1920x1080/uRb-Vjt9Q_ENZ6wA.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112847143245377536/img/yiPkQSfgN85SA9vJ.jpg", "dur": 28}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.01, "thread": [], "tier": "worth"}, {"id": "2112819683703619746", "url": "https://x.com/anandmahindra/status/2112819683703619746", "text": "A Global, iconic brand is being reborn in front of your eyes.\n\nAt @MahindraRise \n\nGet yourself a piece of the action…", "name": "anand mahindra", "handle": "anandmahindra", "avatar": "https://pbs.twimg.com/profile_images/2052825504353501184/uwSdniDR_200x200.jpg", "likes": 7342, "rts": 433, "replies": 182, "views": 299783, "ts": 1792570441, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112819623259516928/vid/avc1/1280x720/7O7mW-fRzI25tbL7.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112819623259516928/vid/avc1/1920x1080/3xLnVnhiRpFbY51S.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112819623259516928/img/4AR8JYbYyVcoKq_B.jpg", "dur": 44}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 5.01, "thread": [], "tier": "worth"}]);